CREATE TABLE "activity_events" ("id" varchar not null, "correlation_id" varchar not null, "actor_type" varchar not null, "actor_id" varchar, "client_id_hash" varchar, "target_id" varchar, "operation" varchar not null, "outcome" varchar not null, "error_code" varchar, "created_at" datetime not null default CURRENT_TIMESTAMP, "target_record_id" varchar, "connector_type_snapshot" varchar, "client_profile_key" varchar, "diagnostic_context" text, primary key ("id"));
CREATE TABLE "activity_retention_state" ("id" integer not null, primary key ("id"));
CREATE TABLE "arvan_api_target_configs" ("id" varchar not null, "target_record_id" varchar not null, "base_url" varchar not null, "spec_url" varchar, "probe_path" varchar, "created_at" datetime, "updated_at" datetime, foreign key("target_record_id") references "targets"("id") on delete cascade, primary key ("id"));
CREATE TABLE "chatgpt_file_admission_guard" ("id" integer not null, primary key ("id"));
CREATE TABLE "chatgpt_file_admission_leases" ("id" varchar not null, "mode" varchar not null, "reserved_bytes" integer not null, "expires_at" datetime not null, "created_at" datetime not null, primary key ("id"));
CREATE TABLE "connection_relays" ("id" varchar not null, "relay_id" varchar not null, "display_name" varchar not null, "control_host" varchar not null, "control_port" integer not null, "control_user" varchar not null, "control_host_key" text not null, "local_socks_port" integer not null, "configuration_revision" integer not null default '1', "lifecycle_revision" integer not null default '1', "enabled" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, "login_public_key" text, "login_private_key_encrypted" text, primary key ("id"));
CREATE TABLE "oauth_access_tokens" ("id" varchar not null, "authorization_id" varchar not null, "client_id" varchar not null, "user_id" integer not null, "resource" varchar not null, "scopes" text not null, "expires_at" datetime not null, "revoked_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("authorization_id") references "oauth_authorizations"("id") on delete cascade, primary key ("id"));
CREATE TABLE "oauth_auth_codes" ("id" varchar not null, "authorization_id" varchar not null, "client_id" varchar not null, "user_id" integer not null, "resource" varchar not null, "scopes" text not null, "expires_at" datetime not null, "revoked_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("authorization_id") references "oauth_authorizations"("id") on delete cascade, primary key ("id"));
CREATE TABLE "oauth_authorizations" ("id" varchar not null, "user_id" integer not null, "client_id" varchar not null, "resource" varchar not null, "resource_hash" varchar not null, "scopes" text not null, "revoked_at" datetime, "created_at" datetime, "updated_at" datetime, "client_profile_key" varchar, "client_profile_generation" integer, foreign key("user_id") references "users"("id") on delete cascade, primary key ("id"));
CREATE TABLE "oauth_client_assertions" ("id" integer primary key autoincrement not null, "client_id" varchar not null, "jti_hash" varchar not null, "expires_at" datetime not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE "oauth_client_profiles" ("profile_key" varchar not null, "client_id" varchar not null, "auth_strategy" varchar not null, "generation" integer not null default '1', "disabled_at" datetime, "created_at" datetime, "updated_at" datetime, primary key ("profile_key"));
CREATE TABLE "oauth_dcr_clients" ("client_id" varchar not null, "profile_key" varchar not null, "secret_hash" varchar not null, "redirect_uris" text not null, "display_name" varchar not null, "retired_at" datetime, "created_at" datetime, "updated_at" datetime, "ever_authorized_at" datetime, "auto_retirement_eligible" tinyint(1) not null default '0', primary key ("client_id"));
CREATE TABLE "oauth_refresh_recoveries" ("old_token_hash" varchar not null, "old_refresh_token_id" varchar not null, "successor_access_token_id" varchar not null, "successor_refresh_token_id" varchar, "authorization_id" varchar not null, "client_id" varchar not null, "user_id" integer not null, "resource" varchar not null, "effective_scopes" text not null, "response_ciphertext" text not null, "recovery_expires_at" datetime not null, "uses_remaining" integer not null default '1', "created_at" datetime, "updated_at" datetime, foreign key("old_refresh_token_id") references "oauth_refresh_tokens"("id") on delete cascade, foreign key("successor_access_token_id") references "oauth_access_tokens"("id") on delete cascade, foreign key("successor_refresh_token_id") references "oauth_refresh_tokens"("id") on delete cascade, foreign key("authorization_id") references "oauth_authorizations"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade, primary key ("old_token_hash"));
CREATE TABLE "oauth_refresh_tokens" ("id" varchar not null, "access_token_id" varchar not null, "authorization_id" varchar not null, "client_id" varchar not null, "user_id" integer not null, "resource" varchar not null, "expires_at" datetime not null, "revoked_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("access_token_id") references "oauth_access_tokens"("id") on delete cascade, foreign key("authorization_id") references "oauth_authorizations"("id") on delete cascade, primary key ("id"));
CREATE TABLE "operational_setting_changes" ("id" varchar not null, "setting_key" varchar not null, "previous_value" integer, "new_value" integer, "version" integer not null, "actor_user_id" integer, "created_at" datetime not null, foreign key("actor_user_id") references "users"("id") on delete set null, primary key ("id"));
CREATE TABLE "operational_settings" ("id" integer primary key autoincrement not null, "overrides" text not null, "version" integer not null default ('0'), "changed_by" integer, "created_at" datetime, "updated_at" datetime, "wp_connect_timeout_seconds" integer, "wp_request_timeout_seconds" integer, "ssh_transfer_max_kib" integer, "ssh_transfer_max_seconds" integer, "ssh_command_timeout_seconds" integer, "ssh_command_max_kib" integer, "ssh_job_max_active_per_user" integer, "ssh_job_max_runtime_seconds" integer, "ssh_job_retention_hours" integer, "ssh_job_preparing_grace_seconds" integer, "ssh_job_reconcile_grace_seconds" integer, "ssh_job_max_script_kib" integer, "ssh_command_stdout_kib" integer, "ssh_command_stderr_kib" integer, "ssh_job_output_window_kib" integer, "ssh_file_read_window_kib" integer, "ssh_file_write_window_kib" integer, "ssh_file_list_name_kib" integer, "wp_ability_input_kib" integer, "dcr_registration_capacity" integer, "batch_max_parallelism" integer, "batch_global_active" integer, "batch_user_active" integer, "batch_worker_max_children" integer, "batch_worker_max_seconds" integer, foreign key("changed_by") references "users"("id") on delete set null on update no action);
CREATE TABLE "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE "ssh_command_jobs" ("id" varchar not null, "target_record_id" varchar, "user_id" integer, "client_identity_hash" varchar not null, "request_id" varchar not null, "script_digest" varchar not null, "target_binding_hash" varchar not null, "unit_mode" varchar, "status" varchar not null, "runtime_seconds" integer not null, "exit_code" integer, "terminal_reason" varchar, "expires_at" datetime not null, "created_at" datetime, "updated_at" datetime, "admission_expires_at" datetime, "operator_attested_at" datetime, "operator_attested_reason" varchar, "operator_attested_uid" integer, "original_user_id" integer, "original_target_record_id" varchar, "original_target_id" varchar, "original_host" varchar, "original_port" integer, "original_os_username" varchar, "original_auth_method" varchar, "original_host_key_digest" varchar, "preparing_expires_at" datetime, "reconcile_grace_seconds" integer, foreign key("user_id") references "users"("id") on delete set null on update no action, foreign key("target_record_id") references "targets"("id") on delete set null on update no action, primary key ("id"));
CREATE TABLE "ssh_direct_target_configs" ("id" varchar not null, "target_record_id" varchar not null, "host" varchar not null, "port" integer not null, "username" varchar not null, "auth_method" varchar not null, "pinned_host_key" text not null, "verification_attempt_id" varchar, "observed_peer_ip" varchar, "observed_at" datetime, "created_at" datetime, "updated_at" datetime, "route_mode" varchar not null default 'direct', "reverse_listener_port" integer, "reverse_tunnel_identity" varchar, "binding_revision" integer not null default '0', foreign key("target_record_id") references "targets"("id") on delete cascade, primary key ("id"));
CREATE TABLE "ssh_job_maintenance_progress" ("operation" varchar not null, "last_expires_at" datetime, "last_id" varchar, "created_at" datetime, "updated_at" datetime, primary key ("operation"));
CREATE TABLE "ssh_reverse_gateway_settings" ("id" integer not null, "enabled" tinyint(1) not null default '0', "publication_pending" tinyint(1) not null default '0', "control_host" varchar not null, "control_port" integer not null, "control_user" varchar not null, "control_host_key" varchar not null, "revision" integer not null default '0', "created_at" datetime, "updated_at" datetime, primary key ("id"));
CREATE TABLE "ssh_reverse_managed_enrollments" ("id" varchar not null, "target_id" varchar not null, "target_record_id" varchar not null, "listener_port" integer not null, "tunnel_identity" varchar not null, "control_public_key" text, "control_key_hash" varchar, "login_public_key" text not null, "token_hash" varchar, "token_expires_at" datetime, "claimed_at" datetime, "activated_at" datetime, "revoked_at" datetime, "state" varchar not null default 'pending', "publication_pending" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("target_record_id") references "targets"("id") on delete cascade, primary key ("id"));
CREATE TABLE "ssh_reverse_managed_retired_ports" ("listener_port" integer not null, "target_id" varchar not null, "retired_at" datetime not null, primary key ("listener_port"));
CREATE TABLE "target_check_operation_targets" ("id" varchar not null, "operation_id" varchar not null, "target_record_id" varchar, "position" integer not null, "target_id_snapshot" varchar not null, "display_name_snapshot" varchar not null, "status" varchar not null, "attempts" integer not null default '0', "attempt_token" varchar, "error_code" varchar, "started_at" datetime, "finished_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("operation_id") references "target_check_operations"("id") on delete cascade, foreign key("target_record_id") references "targets"("id") on delete set null, primary key ("id"));
