CREATE TABLE "target_group_users" ("id" integer primary key autoincrement not null, "target_group_id" varchar not null, "user_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("target_group_id") references "target_groups"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE "target_groups" ("id" varchar not null, "name" varchar not null, "created_at" datetime, "updated_at" datetime, primary key ("id"));
CREATE TABLE "targets" ("id" varchar not null, "target_id" varchar not null, "display_name" varchar not null, "connector_type" varchar not null, "connection_state" varchar not null default ('disconnected'), "last_error_code" varchar, "last_tested_at" datetime, "connected_at" datetime, "last_success_at" datetime, "last_failure_at" datetime, "last_failure_code" varchar, "created_at" datetime, "updated_at" datetime, "operations_paused" tinyint(1) not null default ('0'), "ai_guidance" text, "relay_record_id" varchar, "relay_binding_revision" integer not null default ('0'), "created_by_user_id" integer, foreign key("relay_record_id") references "connection_relays"("id") on delete restrict on update no action, foreign key("created_by_user_id") references "users"("id") on delete set null, primary key ("id"));
